// Block (composition) — a configurable list of loading-placeholder rows.
// Stack owns row arrangement; Skeleton owns placeholder look and this Block owns repeated-row structure.
import type { Ref } from "react";
import { Skeleton } from "../components/Skeleton";
import { Stack } from "../layouts/Stack";
import "./SkeletonList.css";

export interface SkeletonListProps {
  rows?: number;
  showAvatar?: boolean;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function SkeletonList({
  rows = 5,
  showAvatar = false,
  className,
  ref,
}: SkeletonListProps) {
  const rowCount = Math.max(0, Math.floor(rows));

  return (
    <Stack
      ref={ref}
      gap="small"
      aria-busy="true"
      className={className ? `sd-skeletonlist ${className}` : "sd-skeletonlist"}
    >
      {Array.from({ length: rowCount }, (_, index) => (
        <Stack key={index} direction="row" align="center" gap="small" className="sd-skeletonlist__row">
          {showAvatar && (
            <Skeleton
              width="var(--sd-control-height-medium)"
              height="var(--sd-control-height-medium)"
              shape="circle"
              className="sd-skeletonlist__avatar"
            />
          )}
          <Stack gap="2x-small" className="sd-skeletonlist__lines">
            <Skeleton width="100%" height="1rem" />
            <Skeleton width="62%" height="0.75rem" />
          </Stack>
        </Stack>
      ))}
    </Stack>
  );
}

.sd-skeletonlist,
.sd-skeletonlist__lines {
  width: 100%;
}

/* The avatar is a CIRCLE: width and height are the same token, so it must not shrink. The lines
   beside it are `width: 100%`, which in a flex row makes the pair over-wide by the avatar's own
   size and distributes the shortfall by flex-basis, which takes a declared 40x40 down to 36.9x40: an
   oval at every width. Same rule, same reason, as
   `.sd-avatargroup__avatar`. */
.sd-skeletonlist__avatar {
  flex-shrink: 0;
}
